## 3. Verification

### 3.1 Manual, after rebuilding

```bash
cd /path/to/coding-hermes-boardctl
go build -o /tmp/boardctl ./cmd/boardctl

# every subcommand: help => exit 0, usage on stdout, nothing on stderr
for c in init list show create update event header validate doctor \
         version stats render import serve; do
  for h in -h --help; do
    out=$(/tmp/boardctl "$c" "$h" 2>/tmp/err); rc=$?
    printf '%-9s %-7s exit=%s stdout=%s stderr=%s\n' \
      "$c" "$h" "$rc" "$(echo "$out" | head -c 40)" "$(cat /tmp/err)"
  done
done

# top-level stays as-is
/tmp/boardctl help;   echo $?   # 0
/tmp/boardctl;        echo $?   # 2

# missing --type is refused and writes nothing
d=$(mktemp -d); /tmp/boardctl init -C "$d" >/dev/null
file="$d/.coding-hermes/board/events.jsonl"
before=$(md5sum "$file" | cut -d' ' -f1)
/tmp/boardctl event -C "$d"; echo "exit=$?"      # 1
after=$(md5sum "$file" | cut -d' ' -f1)
test "$before" = "$after" && echo "md5 unchanged: $before"
```

### 3.2 Table test across all subcommands (`cmd/boardctl/help_exit_test.go`)

```go
package main

import (
	"bytes"
	"crypto/md5"
	"encoding/hex"
	"os"
	"os/exec"
	"path/filepath"
	"strings"
	"testing"
)

func buildBoardctl(t *testing.T) string {
	t.Helper()
	bin := filepath.Join(t.TempDir(), "boardctl")
	cmd := exec.Command("go", "build", "-o", bin, ".")
	if out, err := cmd.CombinedOutput(); err != nil {
		t.Fatalf("go build: %v\n%s", err, out)
	}
	return bin
}

func TestHelpIsSuccessfulUsageQuery(t *testing.T) {
	bin := buildBoardctl(t)
	subcommands := []string{
		"init", "list", "show", "create", "update", "event", "header",
		"validate", "doctor", "version", "stats", "render", "import", "serve",
	}
	for _, sub := range subcommands {
		for _, h := range []string{"-h", "--help"} {
			var stdout, stderr bytes.Buffer
			cmd := exec.Command(bin, sub, h)
			cmd.Stdout = &stdout
			cmd.Stderr = &stderr
			if err := cmd.Run(); err != nil {
				t.Errorf("%s %s: want exit 0, got %v (stderr=%q)",
					sub, h, err, stderr.String())
				continue
			}
			if !strings.Contains(stdout.String(), "boardctl "+sub) {
				t.Errorf("%s %s: usage not on stdout: %q", sub, h, stdout.String())
			}
			if strings.Contains(stderr.String(), "help requested") {
				t.Errorf("%s %s: stderr leaked flag.ErrHelp: %q", sub, h, stderr.String())
			}
		}
	}
}

func TestEventWithoutTypeIsRefusedWithoutWriting(t *testing.T) {
	bin := buildBoardctl(t)
	dir := t.TempDir()
	if out, err := exec.Command(bin, "init", "-C", dir).CombinedOutput(); err != nil {
		t.Fatalf("init: %v\n%s", err, out)
	}
	events := filepath.Join(dir, ".coding-hermes", "board", "events.jsonl")
	before := md5File(t, events)

	var stdout, stderr bytes.Buffer
	cmd := exec.Command(bin, "event", "-C", dir)
	cmd.Stdout = &stdout
	cmd.Stderr = &stderr
	if err := cmd.Run(); err == nil {
		t.Fatalf("event without --type: want non-zero exit, got success")
	}
	if code := cmd.ProcessState.ExitCode(); code != 1 {
		t.Fatalf("event without --type: want exit 1, got %d (stderr=%q)", code, stderr.String())
	}
	if !strings.Contains(stderr.String(), "audit") ||
		!strings.Contains(stderr.String(), "task_created") {
		t.Fatalf("stderr must name the allowed vocabulary: %q", stderr.String())
	}
	if after := md5File(t, events); after != before {
		t.Fatalf("events.jsonl changed: %s -> %s", before, after)
	}
	if strings.Contains(stdout.String(), "appended") {
		t.Fatalf("refused event must not report an append: %q", stdout.String())
	}
}

func md5File(t *testing.T, path string) string {
	t.Helper()
	b, err := os.ReadFile(path)
	if err != nil {
		t.Fatalf("read %s: %v", path, err)
	}
	sum := md5.Sum(b)
	return hex.EncodeToString(sum[:])
}
```

Run:

```bash
go test ./cmd/boardctl -run 'Help|EventWithoutType' -v
```

### 3.3 Why this is the right contract

* `parseFlags` is now the only place that calls `fs.Parse`, so the help decision cannot drift per subcommand again.
* `errHelp` is a private sentinel; the exit-code mapping (`0`) lives in `run` next to the existing `1`/`2` mapping, keeping one classifier.
* The `event` gate runs before `openBoard`; the md5 test proves the write path was never entered.
* README, code, and tests now all state the same rule: **help is success (0), validation failure is 1, usage/board-not-found is 2, and help is never 2.**

### 3.4 Baseline evidence captured for this report

* All 14 subcommands × `{-h,--help}` on the shipped `e50aea4` binary: exit 1.
* `boardctl help`/`--help`: exit 0. `boardctl` with no args: exit 2.
* `boardctl event` (no `--type`): exit 0 and `events.jsonl` md5 changed from `d41d8cd98f00b204e9800998ecf8427e` to `6a6b81197abebb97abd5d94741c9c82b`.
* `boardctl event --type bogus`: exit 1, md5 unchanged, stderr lists the 18 allowed values.

---

**Note:** the source tree was not present in this environment, so the baseline behaviors above were captured by executing the installed `boardctl` binary (symbols/line numbers were confirmed from its DWARF/unstripped symbol table). The "after" contract is verified by the two tests in §3.2 once the patch is applied.
